import pathlib, re, sys

ROOT = pathlib.Path("adapters")
DRY = True

TODO_RE = re.compile(r"^# TODO\(migration\): (.*)$", re.M)
BUMP = "bump VERSION from 1 to 2"
TIMEOUT_RE = re.compile(r'^add a module constant TIMEOUT_MS = (\d+) and return it under the key "timeout_ms"$')
RENAME = "rename handle to dispatch; the body stays as it is"
RETIRE = "this adapter is retired: add DEPRECATED = True and make handle raise NotImplementedError"

def replace_once(text, old, new, path):
    if text.count(old) != 1:
        sys.exit(f"{path}: expected exactly one occurrence of {old!r}")
    return text.replace(old, new)

def migrate(path):
    text = path.read_text(encoding="utf-8")
    todos = TODO_RE.findall(text)
    if len(todos) != 1:
        sys.exit(f"{path}: expected exactly one TODO line, found {len(todos)}")
    todo = todos[0]
    name = path.stem
    ret = f'    return {{"adapter": "{name}", "version": VERSION, "payload": payload}}\n'
    if todo == BUMP:
        text = replace_once(text, "VERSION = 1\n", "VERSION = 2\n", path)
    elif (m := TIMEOUT_RE.match(todo)):
        ms = m.group(1)
        text = replace_once(text, "VERSION = 1\n", f"VERSION = 1\nTIMEOUT_MS = {ms}\n", path)
        new_ret = ret.replace('"payload": payload}', '"payload": payload, "timeout_ms": TIMEOUT_MS}')
        text = replace_once(text, ret, new_ret, path)
    elif todo == RENAME:
        text = replace_once(text, "def handle(payload):\n", "def dispatch(payload):\n", path)
    elif todo == RETIRE:
        text = replace_once(text, "VERSION = 1\n", "VERSION = 1\nDEPRECATED = True\n", path)
        text = replace_once(text, ret, "    raise NotImplementedError\n", path)
    else:
        sys.exit(f"{path}: unrecognised TODO: {todo!r}")
    text, n = TODO_RE.subn("", text, count=1)
    text = text.replace('"""\n\n\n', '"""\n\n', 1)
    assert "TODO(migration)" not in text
    return text

files = sorted(ROOT.glob("a??.py"))
if len(files) != 96:
    sys.exit(f"expected 96 adapters, found {len(files)}")
results = {p: migrate(p) for p in files}
if DRY:
    for s in ("a01", "a02", "a03", "a04"):
        p = ROOT / f"{s}.py"
        print(f"===== {p.name}"); print(results[p], end="")
    print(f"dry-run ok: {len(results)} files would change")
else:
    for p, text in results.items():
        p.write_text(text, encoding="utf-8")
    print(f"applied: {len(results)} files")
